import{_ as r,o,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"クイックパネル","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/quick-panel.md","filePath":"ja-JP/user-guide/settings/quick-panel.md","lastUpdated":1786082398000}'),e={name:"ja-JP/user-guide/settings/quick-panel.md"};function l(a,t,i,g,d,h){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="クイックパネル" tabindex="-1">クイックパネル <a class="header-anchor" href="#クイックパネル" aria-label="Permalink to &quot;クイックパネル&quot;">​</a></h1><p>パネルを開いている間、現在選択しているグループの見出しに表示されたフォルダーも現在のディレクトリとして扱われます。選択項目がファイルかフォルダーかは関係ありません。見出しのパスが空でなければ、対応するファイルダイアログでクイック切り替え（既定は <code>Ctrl+G</code>）を使ってその場所へ移動できます。</p><p>ホットキーで呼び出し、前面にあるウィンドウの右下隅に、その高さと幅のちょうど半分のサイズでドッキングするフローティングパネルです。指定したフォルダーの中身と、プラグインが提供する一覧を、サムネイルタイルまたは一覧で表示するので、作業中のウィンドウを離れずにファイルを取り出したり、ドラッグして持ち出したり、逆にドロップして入れたりできます。上端をドラッグすれば、今回の呼び出しの間だけ別の場所へ移動できます。</p><ul><li><strong>クイックパネルを有効にする</strong> — マスタースイッチ。オフにするとホットキーを押しても何も起きません。</li></ul><p>呼び出すキーは<a href="./hotkeys-page.html">ホットキー</a>ページにあります(既定は <code>Ctrl+F2</code>)。</p><h2 id="ワークスペース" tabindex="-1">ワークスペース <a class="header-anchor" href="#ワークスペース" aria-label="Permalink to &quot;ワークスペース&quot;">​</a></h2><p>パネルは一度に1つのタブを表示し、<strong>ワークスペース</strong>はそのうちの1種類です。ワークスペースとは、ある種類の作業のために集めたソースの組です — あるプロジェクトのフォルダー群、参考資料を置いている場所、ものを放り込むための受け皿など。</p><p>左側のリストがワークスペースそのもので、<strong>新しいワークスペース</strong>、<strong>ワークスペースを複製</strong>、<strong>ワークスペースを削除</strong>のボタンと、設定の他の場所と同じ上下矢印(またはドラッグ)による並べ替えリスト(<a href="./favorites.html">お気に入り</a>を参照)が付いています。ここでの上から下が、パネルのタブストリップでの左から右になります。</p><ul><li><strong>名前</strong> — タブに表示される文字。空のままにすると翻訳済みの既定名にフォールバックするので、一度も名前を変えていないワークスペースは UI 言語に追従します。</li><li><strong>有効</strong> — 各ワークスペースの横のチェックボックス。オフにすると設定は残したままタブだけがなくなります。今月は使わないが、削除するとソース一覧を組み直す羽目になるワークスペース向けです。ライブパネルのタブにある <strong>×</strong> はまさにこれを行うので、戻すのはここからになります。</li></ul><p>選択中のワークスペースは2つのサブタブで編集します:<strong>ソース</strong>と<strong>アプリ</strong>。</p><h2 id="ソース" tabindex="-1">ソース <a class="header-anchor" href="#ソース" aria-label="Permalink to &quot;ソース&quot;">​</a></h2><p>各ソースがパネルの1つのグループになり、このリストの順序で表示されます。<strong>フォルダーを追加</strong>で追加します。各行のチェックボックスはそのグループを削除せずに非表示にし、名前のボックスはグループの見出しを上書きします(空ならフォルダー自身の名前)。<strong>その他のオプション</strong>に残りの設定があります:</p><ul><li><strong>表示</strong> — そのグループがフォルダーから何を取り出すか: <ul><li><strong>最近変更されたファイル</strong> — 最近変更されたものだけを新しい順に。フォルダーを走査するのではなくインデックスが答えます。</li><li><strong>すべて、新しい順</strong> — 古いという理由でファイルを隠すことはなく、何を先に出すかだけを決めます。</li><li><strong>すべて、名前順</strong> — フォルダーをショートカットバーとして使う場合。</li></ul></li><li><strong>フォルダー</strong> — フォルダーそのもの。隣の <strong>…</strong> ボタンで参照できます。</li><li><strong>サブフォルダーを含む</strong> — 既定はオフ。</li><li><strong>ドロップされたファイルを受け入れる</strong> — このグループにドラッグしたファイルやフォルダーを、Windows 自身のファイルコピー(その進行状況ダイアログ、競合の確認、元に戻す操作)でこのフォルダーへコピーします。常にコピーで、移動になることはありません。既定はオフで、ソースごとに個別に指定します:受け皿として使うフォルダーには必要で、読むだけのフォルダーには不要だからです。</li><li><strong>フィルター</strong> — <code>;</code> または <code>,</code> で区切った1つ以上のパターン(例:<code>*.mp4;*.mkv</code>)で、このソースに表示する内容を任意に絞り込みます。既定の空欄はフィルターなしです。</li><li><strong>最大</strong> — このグループが表示する最大件数。0 はソースにあるものすべて。</li><li><strong>変更が次の時間内(分)</strong> — この時間内に変更されたものだけが対象になります。0 は期間制限なし。</li><li><strong>一覧で表示</strong> — このグループをサムネイルタイルではなく詳細一覧で開きます。どちらが合うかはフォルダーの性質次第です:画像はタイル、文書は名前と日付。タイルは1行を5つで<strong>等分</strong>します — 広いウィンドウにドッキングしたパネルでは、数が増えるのではなく見るに値する大きさのサムネイルになります。5は固定ではありません:5つでもサムネイルが埋められる幅を超えるほど広ければ数が増え、5つでは判別できないほど狭ければ数が減ります。いくつになっても1行は固定サイズを並べるのではなく<strong>等分</strong>するので、行末に隙間が残ることはありません。絵はそれぞれの比率のままなので、16:9の動画ばかりのフォルダーが、上下に余白の帯を抱えた縦長の箱の並びになることもありません。</li></ul><p>ここで追加したフォルダーは既定で<strong>すべて、名前順</strong>です — 手で選んだフォルダーは、たいてい物が置いてある場所だからです。新規インストール時のワークスペースだけは例外で、それも意図的です:デスクトップ、ダウンロード、ドキュメントは物が届く場所なので、最近変更されたファイルで始まります。</p><h2 id="プラグインタブ" tabindex="-1">プラグインタブ <a class="header-anchor" href="#プラグインタブ" aria-label="Permalink to &quot;プラグインタブ&quot;">​</a></h2><p>プラグインが提供するタブで、どれかのワークスペースの中ではなく、ページ自身の2つめのタブに並びます:プラグインが差し出すのは一揃いのコレクションであり、このワークスペースのフォルダーとも、あのワークスペースのフォルダーとも、特に近しいわけではないからです。各タブはパネル全体に対して一度チェックすればストリップに入り、外せば出ていきます。</p><p>CoreExtensions には5つ同梱されています:</p><table tabindex="0"><thead><tr><th>タブ</th><th>何が並ぶか</th></tr></thead><tbody><tr><td><strong>お気に入り</strong></td><td>あなたの<a href="./favorites.html">お気に入り</a>を、並べた順のまま。中の URL はブラウザーで開きます。</td></tr><tr><td><strong>履歴</strong></td><td>Lertaro 自身から開いたもの。新しい順 — この中でアプリケーションを含むのはこれだけです。</td></tr><tr><td><strong>Windows の最近使った項目</strong></td><td>シェル自身の最近使ったドキュメントの一覧を、指し示す実ファイルへ解決したもの。新しい順。</td></tr><tr><td><strong>最後のフォルダー</strong></td><td>最後に見ていたフォルダー — エクスプローラーでも、どのアプリのファイルダイアログでも構いません。直前まで居た場所をそのまま差し出せます。</td></tr><tr><td><strong>最近使ったファイル</strong></td><td>パネルが見るように設定されたフォルダー群の中で最も新しいファイル。フォルダーを歩き回るのではなくインデックスが答えます。ファイルのみ。</td></tr></tbody></table><ul><li>チェックボックスはそのタブをストリップに入れるか外すかを決めます。パネル上のタブの <strong>×</strong> も同じことなので、戻すのはここです。</li><li><strong>一覧で表示</strong> — そのタブをサムネイルタイルではなく詳細一覧で開きます。フォルダーソースと同じ選択肢で、ここで訊いているのは、プラグインタブにはソースリストの中に自分の行がないからです。パネル側の見出しの表示切り替えは、開いている間に限りこれを上書きします。</li><li>リストに載るのは<a href="./plugins.html">プラグイン</a>ページでコンポーネントが有効になっているタブだけですが、それは別の問いです:ここでチェックを外すのはストリップから外すだけ、あちらで無効にするのはそもそも動かさないということ。プラグインをオフにしている間に閉じたタブは、プラグインが戻ってきても閉じたままです — この状態はコンポーネントに対して保存されており、そのとき読み込まれているものから組み立て直しているわけではありません。</li></ul><p>プラグインタブは一覧を1つだけ持ち、グループの見出しは付きません — タブ自体がすでにその名前だからです。ファイルのドロップは受け付けず、何も返さなかったプラグインにはタブ自体ができません。</p><h2 id="アプリ" tabindex="-1">アプリ <a class="header-anchor" href="#アプリ" aria-label="Permalink to &quot;アプリ&quot;">​</a></h2><p>このワークスペースが属するアプリケーションを、1行につき1つのプロセス名で指定します(<code>chrome</code> でも <code>chrome.exe</code> でも構いません)。そのいずれかの上でパネルを呼び出すと、前回の状態ではなくこのワークスペースで開きます — 今いるアプリ自体が、どのフォルダー群のことなのかを語っているからです。空にすると、このワークスペースは手動でしか開けません。</p><h2 id="クイックパネルのみ" tabindex="-1">クイックパネルのみ <a class="header-anchor" href="#クイックパネルのみ" aria-label="Permalink to &quot;クイックパネルのみ&quot;">​</a></h2><p>パネルが立ち入らないアプリケーションを、1行につき1つのプロセス名で指定します。グローバルな<a href="./hotkeys-page.html#process-blacklist">プロセスのブラックリスト</a>を置き換えるのではなく、その上に<strong>追加</strong>されます:グローバルでブロックされているものはここでもブロックされます。このリストは、このパネルだけが避ける理由を持つアプリのためのものです — 前面のウィンドウに自分を貼り付けるので、全画面のプレーヤーやゲームは台無しになりますが、だからといってグローバルなブロックに値するわけではありません。</p><h2 id="パネルの使い方" tabindex="-1">パネルの使い方 <a class="header-anchor" href="#パネルの使い方" aria-label="Permalink to &quot;パネルの使い方&quot;">​</a></h2><ul><li><strong>フィルターボックス</strong> — タブストリップの右にあり、パネルが開いた瞬間にフォーカスが入ります。あいまい検索(検索ウィンドウと同じ fzf 方式のマッチング、ピンインエイリアスを含む)で、対象は現在のワークスペースだけです。フィルター中に一致が1件もなくなったグループは非表示になります。</li><li><strong>Enter</strong> は選択中の項目を開きます。ダブルクリックと同じです。最初の項目が初めから選択されているので、呼び出してからフィルターボックスを離れることなく「入力して Enter」だけで完結します。</li><li><strong>上下キー</strong>は選択を動かし、グループの最後の行で止まらずに次のグループへ入っていきます — 全グループが上から下へひと続きのリストとして扱われます。フィルターボックスからも使え、キーボードがボックスから離れることはないので、絞り込みと選択がひと続きの操作になります。タイル表示のグループの中では、これまでどおりグリッドの行単位で移動します。設定の「次/前の項目を選択」ホットキー(既定は <code>Ctrl+N</code>/<code>Ctrl+P</code>)も同じ動作です。ただし同じキーにプラグインのアクションが割り当てられている場合は、そちらが優先されます。</li><li><strong>タブの切り替え</strong> — 「N番目の結果へジャンプ」の修飾キー(既定は <code>Ctrl</code>、<a href="./../hotkeys.html">ホットキー</a>参照)を押しながら 1〜9、またはタブをクリック。ワークスペースとプラグインタブは1本のタブストリップと1つの並び順を共有します。タブはドラッグで並べ替えられ、それぞれの <strong>×</strong> はそのタブをストリップから外します(ワークスペースはオフに、プラグインタブは閉じた状態に — どちらも上の設定で戻せます)。最後の1つを閉じるとパネル自体が閉じます。</li><li><strong>グループの見出し</strong>には並べ替えの切り替え(名前順/更新日時順)、表示の切り替え(タイル/一覧)、折りたたみの矢印があります。見出し本体または矢印をクリックすると、標準的な Windows のグループ見出しのように開閉できます。並べ替えと表示のコントロールはそれぞれの操作を続けます。ここでの操作はパネルが開いている間だけ有効で、初期状態は上の設定が決めます。</li><li><strong>行番号</strong> — すべてのグループで左側の余白を共有します。リスト表示では項目、タイル表示では視覚上の行に番号を付けます。余白の幅は表示中のグループで最大の番号に合わせるため、番号は常に揃います。グループの開閉は折りたたみの矢印を操作したときだけで、スクロールでは変わりません。</li><li><strong>複数選択</strong> — タイル表示では、空いている場所をドラッグして矩形選択できます。選択は1つのグループに属します(グループごとに独立したリストを描画しているため)。空白をクリックすると選択が解除されます。</li><li><strong>ファイルのドロップ</strong> — ファイル、フォルダー、あるいは Web ページから直接ドラッグした画像を、ドロップを受け入れるグループへ落とします。ドラッグがファイルとして提供できるものはすべて受け取り、画像に限りません。コピーが終わるとそのグループは自動で読み込み直します。</li><li><strong>プレビュー</strong> — QuickLook のキー(既定は <code>Alt+P</code>。他のホットキーと同じく<a href="./hotkeys-page.html">ホットキー</a>ページで変更できます)で、選択中のファイルのプレビューウィンドウが開き、以後は選択に追従します。ドッキングするのはパネルの右側で、画面の端に阻まれて収まらないときだけ左側に回ります — 最大化したウィンドウの右下隅にいるパネルがまさにその場合です。プレビューをクリックしてもパネルは消えず、その両方から離れたときに消えます。パネルを閉じると一緒に閉じます。</li><li><strong>閉じないようにする</strong> — パネルはフォーカスを失うと閉じます。ピン留めボタン、または「ウィンドウを閉じない」ホットキー(既定は <code>Ctrl+T</code>、クイックウィンドウと同じキー)で、今回の呼び出しの間だけそれを止められます。</li><li><strong>Esc</strong> はフィルターボックスに文字があればそれを消し、なければパネルを閉じます。</li><li>パネルは自身を最新に保ちます:表示中のフォルダーがディスク上で変化すると読み込み直します。独自のスキャンではなく、アプリ全体で使っているインデックスベースの監視を通じて行われます。</li></ul>',26)])])}const u=r(e,[["render",l]]);export{p as __pageData,u as default};
